:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c63ff;
  --primary-hover: #5a52d5;
  --text: #e0e0f0;
  --text-muted: #a0a0b8;
  --error: #ff6b6b;
  --radius: 12px;
  font-size: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  padding: 2rem;
  width: 100%;
  max-width: 480px;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
}

.subtitle {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.form-group {
  margin-bottom: 1rem;
  flex: 1;
}

.form-row {
  display: flex;
  gap: 1rem;
}

label {
  display: block;
  margin-bottom: 0.35rem;
  font-weight: 600;
  font-size: 0.95rem;
}

input, select {
  width: 100%;
  padding: 0.65rem 0.75rem;
  border: 2px solid transparent;
  border-radius: 8px;
  background: #3a3a55;
  color: var(--text);
  font-size: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

input:hover, select:hover {
  border-color: #5a5a80;
}

.btn-primary {
  width: 100%;
  padding: 0.75rem;
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn-primary:hover {
  background: var(--primary-hover);
}

.btn-primary:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn-primary:active {
  transform: scale(0.98);
}

.error {
  color: var(--error);
  font-size: 0.9rem;
  min-height: 1.4rem;
  margin-bottom: 0.5rem;
}

.course-list-section {
  margin-top: 2rem;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.course-list {
  list-style: none;
}

.course-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 0;
  border-bottom: 1px solid #3a3a55;
  gap: 0.5rem;
}

.course-info {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  font-size: 0.95rem;
}

.course-name {
  font-weight: 600;
}

.course-meta {
  color: var(--text-muted);
}

.btn-remove {
  background: transparent;
  border: 1px solid var(--error);
  color: var(--error);
  border-radius: 6px;
  padding: 0.3rem 0.6rem;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}

.btn-remove:hover {
  background: var(--error);
  color: #fff;
}

.btn-remove:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.btn-remove:active {
  transform: scale(0.95);
}

.empty-message {
  color: var(--text-muted);
  font-style: italic;
  padding: 0.5rem 0;
}

.gpa-section {
  margin-top: 2rem;
  text-align: center;
}

.gpa-display {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  .form-row {
    flex-direction: column;
    gap: 0;
  }
  .course-item {
    flex-direction: column;
    align-items: flex-start;
  }
  .btn-remove {
    align-self: flex-end;
  }
}

const courses = [];
const gradePoints = { A: 4.0, B: 3.0, C: 2.0, D: 1.0, F: 0.0 };

const form = document.getElementById('course-form');
const nameInput = document.getElementById('course-name');
const creditsInput = document.getElementById('course-credits');
const gradeSelect = document.getElementById('course-grade');
const errorEl = document.getElementById('form-error');
const listEl = document.getElementById('course-list');
const emptyMsg = document.getElementById('empty-message');
const gpaDisplay = document.getElementById('gpa-display');

function validate(name, credits, grade) {
  if (!name.trim()) return 'Course name is required.';
  const cred = Number(credits);
  if (!Number.isInteger(cred) || cred < 1) return 'Credit hours must be a positive integer.';
  if (!grade) return 'Please select a letter grade.';
  return null;
}

function calculateGPA() {
  if (courses.length === 0) return 0;
  let totalPoints = 0;
  let totalCredits = 0;
  courses.forEach(c => {
    totalPoints += gradePoints[c.grade] * c.credits;
    totalCredits += c.credits;
  });
  return totalCredits > 0 ? totalPoints / totalCredits : 0;
}

function render() {
  listEl.innerHTML = '';
  if (courses.length === 0) {
    emptyMsg.style.display = 'block';
  } else {
    emptyMsg.style.display = 'none';
    courses.forEach((course, index) => {
      const li = document.createElement('li');
      li.className = 'course-item';

      const info = document.createElement('div');
      info.className = 'course-info';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'course-name';
      nameSpan.textContent = course.name;

      const creditsSpan = document.createElement('span');
      creditsSpan.className = 'course-meta';
      creditsSpan.textContent = `${course.credits} credit${course.credits > 1 ? 's' : ''}`;

      const gradeSpan = document.createElement('span');
      gradeSpan.className = 'course-meta';
      gradeSpan.textContent = `Grade: ${course.grade}`;

      info.append(nameSpan, creditsSpan, gradeSpan);

      const removeBtn = document.createElement('button');
      removeBtn.className = 'btn-remove';
      removeBtn.textContent = 'Remove';
      removeBtn.setAttribute('aria-label', `Remove ${course.name}`);
      removeBtn.addEventListener('click', () => {
        courses.splice(index, 1);
        render();
      });

      li.append(info, removeBtn);
      listEl.appendChild(li);
    });
  }

  const gpa = calculateGPA();
  gpaDisplay.textContent = gpa.toFixed(2);
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = nameInput.value;
  const credits = creditsInput.value;
  const grade = gradeSelect.value;

  const error = validate(name, credits, grade);
  if (error) {
    errorEl.textContent = error;
    return;
  }

  errorEl.textContent = '';
  courses.push({ name: name.trim(), credits: Number(credits), grade });
  form.reset();
  nameInput.focus();
  render();
});

render();
